      "没人分工、没人写游戏逻辑，全靠游戏内聊天与一份共享笔记自己拆活、互相捡回掉落的物品",
      "全程写 2,783 个程序、6 万多行 JavaScript、说 229 句话、死 605 次，22% 的程序以报错收场",
      "成本约 520 美元（入门价）：13.5 亿输入 token 中 91% 走缓存，约 24,000 次模型调用",
      "第五个「观察者」只看不玩，未发现规格作弊；研究员随时可停，但 27 小时里没找到插手的理由",
